"use server"
import { db } from "@/prisma/db"
import type { CreateEventFormData } from "@/types/event"
import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"



export async function createEvent(data: CreateEventFormData){
   await db.orm.public.Event.create({
    title: data.title,
    description: data.description,
    location: data.location,
    date: Temporal.Instant.fromEpochMilliseconds(new Date(data.date).getTime())
   })
   revalidatePath("/events")
   redirect("/events")

    
}

export async function updateEvent(id: string, data: CreateEventFormData){
    await db.orm.public.Event
    .where({ id })
    .update({
        title: data.title,
        description: data.description,
        location: data.location,
        date: Temporal.Instant.fromEpochMilliseconds(new Date(data.date).getTime())
    })
    revalidatePath("/events")
    revalidatePath(`/events/${id}`)
    redirect(`/events/${id}`)
}

export async function deleteEvent(id: string){
    await db.orm.public.Event
    .where({ id })
    .delete()
    revalidatePath("/events")
    redirect("/events")
}